      "source_answer": "A. มีข้อมูล 3 ชุด เก็บไว้ในสื่อ 2 ประเภท และเก็บไว้นอกสถานที่ 1 ชุด",
      "explanation_th": [
        "มีข้อมูล 3 ชุด เก็บไว้ในสื่อ 2 ประเภท และเก็บไว้นอกสถานที่ 1 ชุด \nเพราะหลักสำรองข้อมูลแบบ 3-2-1 หมายถึง \n\n• มีข้อมูลทั้งหมดอย่างน้อย 3 ชุด ได้แก่ ข้อมูลต้นฉบับ 1 ชุดและข้อมูลสำรองอีก 2 ชุด \n \n• เก็บไว้บนสื่ออย่างน้อย 2 ประเภท เช่น ฮาร์ดดิสก์และระบบ Cloud \n \n• เก็บข้อมูลสำรองอย่างน้อย 1 ชุดไว้นอกสถานที่หลัก \nหลักนี้ช่วยลดความเสี่ยงจากฮาร์ดดิสก์เสีย ไฟไหม้ น้ำท่วม การโจรกรรม หรือการโจมตีด้วย Ransomware"
      ],
