        "ใช้รหัสผ่านร่วมกับ OTP หรือลายนิ้วมือ \nเพราะ Two-Factor Authentication หรือ 2FA \nต้องใช้หลักฐานยืนยันตัวตนจากอย่างน้อยสองประเภทที่แตกต่างกัน เช่น \n\n1. สิ่งที่ผู้ใช้รู้ เช่น รหัสผ่านหรือ PIN \n \n2. สิ่งที่ผู้ใช้มี เช่น โทรศัพท์หรืออุปกรณ์สร้าง OTP \n \n3. สิ่งที่เป็นลักษณะเฉพาะของผู้ใช้ เช่น ลายนิ้วมือหรือใบหน้า \nดังนั้น การใช้รหัสผ่านร่วมกับ OTP หรือลายนิ้วมือจึงเป็นการยืนยันตัวตนสองปัจจัย \nการใช้รหัสผ่านสองครั้งยังถือว่าเป็นปัจจัยประเภทเดียวกัน จึงไม่ใช่ 2FA ที่แท้จริง"
