      "id": "mock-it-74",
      "subject": "it",
      "question_number": 74,
      "question_text": "เมื่อเจ้าหน้าที่จำเป็นต้องใช้ Wi-Fi สาธารณะ ควรปฏิบัติอย่างไรจึงปลอดภัยที่สุด",
      "choices": {
        "A": "เปิดการแชร์ไฟล์ให้ผู้ใช้ทุกคน",
        "B": "หลีกเลี่ยงการทำธุรกรรมสำคัญ และใช้ VPN เมื่อจำเป็น",
        "C": "ปิดโปรแกรมป้องกันไวรัสเพื่อเพิ่มความเร็ว",
        "D": "บันทึกรหัสผ่านทุกบัญชีไว้ในเว็บเบราว์เซอร์"
      },
      "correct_answer": "B",
      "source_answer": "B. หลีกเลี่ยงการทำธุรกรรมสำคัญ และใช้ VPN เมื่อจำเป็น",
      "explanation_th": [
        "หลีกเลี่ยงการทำธุรกรรมสำคัญ และใช้ VPN เมื่อจำเป็น \nเพราะ Wi-Fi สาธารณะอาจมีความปลอดภัยไม่เพียงพอ ผู้ไม่หวังดีอาจดักรับข้อมูล สร้างจุดเชื่อมต่อปลอม \nหรือพยายามเข้าถึงอุปกรณ์ที่เชื่อมต่ออยู่ในเครือข่ายเดียวกัน \nแนวทางที่เหมาะสม ได้แก่ \n• หลีกเลี่ยงการทำธุรกรรมทางการเงิน \n \n• ไม่กรอกรหัสผ่านหรือข้อมูลลับโดยไม่จำเป็น \n \n• ใช้เว็บไซต์ HTTPS \n \n• ใช้ VPN ที่น่าเชื่อถือเมื่อจำเป็น \n \n• ปิดการแชร์ไฟล์และการเชื่อมต่ออัตโนมัติ \n\nตัวเลือกอื่นเพิ่มความเสี่ยง เพราะการเปิดแชร์ไฟล์ ปิดโปรแกรมป้องกันไวรัส \nหรือบันทึกรหัสผ่านโดยไม่ระมัดระวัง อาจทำให้ข้อมูลถูกเข้าถึงได้ง่ายขึ้น"
      ],
