        "ไม่เปิ ดไฟล์ และตรวจสอบผู้ส่งก่อน \nเพราะไฟล์นามสกุล .exe เป็นไฟล์โปรแกรมที่สามารถสั่งให้คอมพิวเตอร์ทางานได้ หากมาจากบุคคลที่ไม่รู้จัก \nอาจเป็นมัลแวร์ ไวรัส โทรจัน หรือโปรแกรมขโมยข้อมูล \nการเปลี่ยนชื่อไฟล์ไม่ได้ทำให้ไฟล์ปลอดภัย ส่วนการส่งให้เพื่อนทดลองเปิดเป็นการส่งต่อความเสี่ยง \nและไม่ควรเปิดไฟล์ทันทีเพียงเพื่อตรวจสอบเนื้อหา \nควรตรวจสอบผู้ส่ง แหล่งที่มาของไฟล์ และสแกนไฟล์ด้วยระบบรักษาความปลอดภัยก่อนเสมอ"
