        "Switch \nเพราะ Switch ใช้เชื่อมต่อคอมพิวเตอร์และอุปกรณ์หลายเครื่องภายในเครือข่าย LAN โดยจะเรียนรู้หมายเลข \nMAC Address ของอุปกรณ์ แล้วส่งข้อมูลไปยังพอร์ตที่เชื่อมต่อกับอุปกรณ์ปลายทาง \n• Modem ใช้แปลงสัญญาณเพื่อเชื่อมต่อกับผู้ให้บริการอินเทอร์เน็ต \n \n• Printer เป็นอุปกรณ์แสดงผลบนกระดาษ \n \n• Scanner เป็นอุปกรณ์รับข้อมูล \nSwitch จึงเหมาะสำหรับเชื่อมต่ออุปกรณ์ภายในเครือข่ายสำนักงานหรือสถานีตำรวจ"
